130	    fn from_plugin(plugin: &LoadedPlugin) -> Option<Self> {
131	        if !plugin.is_active() {
132	            return None;
133	        }
134	
135	        let mut mcp_server_names: Vec<String> = plugin.mcp_servers.keys().cloned().collect();
136	        mcp_server_names.sort_unstable();
137	
138	        let summary = Self {
139	            config_name: plugin.config_name.clone(),
140	            display_name: plugin
141	                .manifest_name
142	                .clone()
143	                .unwrap_or_else(|| plugin.config_name.clone()),
144	            description: plugin.manifest_description.clone(),
145	            has_skills: !plugin.skill_roots.is_empty(),
146	            mcp_server_names,
147	            app_connector_ids: plugin.apps.clone(),
148	        };
149	
150	        (summary.has_skills
151	            || !summary.mcp_server_names.is_empty()
152	            || !summary.app_connector_ids.is_empty())
153	        .then_some(summary)
154	    }
155	}
