608	    pub fn list_marketplaces_for_config(
609	        &self,
610	        config: &Config,
611	        additional_roots: &[AbsolutePathBuf],
612	    ) -> Result<Vec<ConfiguredMarketplaceSummary>, MarketplaceError> {
613	        let installed_plugins = configured_plugins_from_stack(&config.config_layer_stack)
614	            .into_keys()
615	            .filter(|plugin_key| {
616	                PluginId::parse(plugin_key)
617	                    .ok()
618	                    .is_some_and(|plugin_id| self.store.is_installed(&plugin_id))
619	            })
620	            .collect::<HashSet<_>>();
621	        let configured_plugins = self
622	            .plugins_for_config(config)
623	            .plugins()
624	            .iter()
625	            .map(|plugin| (plugin.config_name.clone(), plugin.enabled))
626	            .collect::<HashMap<String, bool>>();
627	        let marketplaces = list_marketplaces(&self.marketplace_roots(additional_roots))?;
628	        let mut seen_plugin_keys = HashSet::new();
629	
630	        Ok(marketplaces
631	            .into_iter()
632	            .filter_map(|marketplace| {
633	                let marketplace_name = marketplace.name.clone();
634	                let plugins = marketplace
635	                    .plugins
636	                    .into_iter()
637	                    .filter_map(|plugin| {
638	                        let plugin_key = format!("{}@{marketplace_name}", plugin.name);
639	                        if !seen_plugin_keys.insert(plugin_key.clone()) {
640	                            return None;
641	                        }
642	
643	                        Some(ConfiguredMarketplacePluginSummary {
644	                            // Enabled state is keyed by `<plugin>@<marketplace>`, so duplicate
645	                            // plugin entries from duplicate marketplace files intentionally
646	                            // resolve to the first discovered source.
647	                            id: plugin_key.clone(),
648	                            installed: installed_plugins.contains(&plugin_key),
649	                            enabled: configured_plugins
650	                                .get(&plugin_key)
651	                                .copied()
652	                                .unwrap_or(false),
653	                            name: plugin.name,
654	                            source: plugin.source,
655	                            install_policy: plugin.install_policy,
656	                            auth_policy: plugin.auth_policy,
657	                            interface: plugin.interface,
658	                        })
659	                    })
660	                    .collect::<Vec<_>>();
661	
662	                (!plugins.is_empty()).then_some(ConfiguredMarketplaceSummary {
663	                    name: marketplace.name,
664	                    path: marketplace.path,
665	                    plugins,
666	                })
667	            })
668	            .collect())
