53	fn assert_schema_trees_match(
54	    label: &str,
55	    fixture_tree: &BTreeMap<PathBuf, Vec<u8>>,
56	    generated_tree: &BTreeMap<PathBuf, Vec<u8>>,
57	) -> Result<()> {
58	    let fixture_paths = fixture_tree
59	        .keys()
60	        .map(|p| p.display().to_string())
61	        .collect::<Vec<_>>();
62	    let generated_paths = generated_tree
63	        .keys()
64	        .map(|p| p.display().to_string())
65	        .collect::<Vec<_>>();
66	
67	    if fixture_paths != generated_paths {
68	        let expected = fixture_paths.join("\n");
69	        let actual = generated_paths.join("\n");
70	        let diff = TextDiff::from_lines(&expected, &actual)
71	            .unified_diff()
72	            .header("fixture", "generated")
73	            .to_string();
74	
75	        panic!(
76	            "Vendored {label} app-server schema fixture file set doesn't match freshly generated output. \
77	Run `just write-app-server-schema` to overwrite with your changes.\n\n{diff}"
78	        );
79	    }
80	
81	    // If the file sets match, diff contents for each file for a nicer error.
82	    for (path, expected) in fixture_tree {
83	        let actual = generated_tree
84	            .get(path)
85	            .ok_or_else(|| anyhow::anyhow!("missing generated file: {}", path.display()))?;
86	
87	        if expected == actual {
88	            continue;
89	        }
90	
91	        let expected_str = String::from_utf8_lossy(expected);
92	        let actual_str = String::from_utf8_lossy(actual);
93	        let diff = TextDiff::from_lines(&expected_str, &actual_str)
94	            .unified_diff()
95	            .header("fixture", "generated")
96	            .to_string();
97	        panic!(
98	            "Vendored {label} app-server schema fixture {} differs from generated output. \
99	Run `just write-app-server-schema` to overwrite with your changes.\n\n{diff}",
100	            path.display()
101	        );
102	    }
103	
104	    Ok(())
105	}
